// Session replay path gate for the docs site.
//
// Replay is enabled for ONE reason: skill and hook reference pages bounce at
// about 100%, and the numbers alone cannot say why. So recording is allowed on
// /docs/reference/* and nowhere else. This module is that rule, kept free of
// posthog-js and of window so it can be unit-tested; instrumentation-client.ts
// wires it to the SDK and to the App Router.
//
// The PostHog project's URL trigger may say the same thing, but this gate does
// not rely on it. It is complete on its own: the SDK is initialised with replay
// disabled, and only this gate ever turns it on.

import type { CapturedNetworkRequest } from "posthog-js";

export const REPLAY_PATH_PREFIX = "/docs/reference/";

/** True only for pages under /docs/reference/ (the index at /docs/reference is excluded). */
export function isReplayPath(pathname: string): boolean {
	return pathname.startsWith(REPLAY_PATH_PREFIX);
}

/** Resolve an href (absolute or relative) to its pathname, or null when unparseable. */
export function pathnameOf(href: string, base: string): string | null {
	try {
		return new URL(href, base).pathname;
	} catch {
		return null;
	}
}

/** The two SDK calls the gate needs. posthog-js satisfies it structurally. */
export interface ReplayControls {
	startSessionRecording(): void;
	stopSessionRecording(): void;
}

export interface ReplayGate {
	/** Start replay if `pathname` is a reference page, stop it otherwise. */
	sync(pathname: string): void;
	/** Stop replay unconditionally (used before leaving a reference page). */
	stop(): void;
}

export function createReplayGate(controls: ReplayControls): ReplayGate {
	// Tracks what this gate asked for, not whether the SDK is recording yet. The
	// SDK can still be waiting on remote config after start(), and a navigation
	// away in that window must still stop it, so the flag, not
	// sessionRecordingStarted(), decides whether stop() is owed.
	let requested = false;

	const stop = () => {
		if (!requested) return;
		requested = false;
		controls.stopSessionRecording();
	};

	return {
		sync(pathname) {
			if (!isReplayPath(pathname)) {
				stop();
				return;
			}
			if (requested) return;
			requested = true;
			// No override argument on purpose: sampling, linked flag and any URL
			// trigger configured in the PostHog project still apply on top of
			// this gate. The gate can only narrow recording, never widen it.
			controls.startSessionRecording();
		},
		stop,
	};
}

/**
 * Network capture mask for replay. Drops every header and body, and strips the
 * query string and fragment from the URL. The fetch the search dialog makes
 * carries the typed query in its query string, so the URL has to go too, not
 * just the payload.
 */
export function maskNetworkRequest(
	request: CapturedNetworkRequest,
): CapturedNetworkRequest {
	return {
		...request,
		name: stripQueryAndHash(request.name),
		requestHeaders: undefined,
		requestBody: null,
		responseHeaders: undefined,
		responseBody: null,
	};
}

function stripQueryAndHash(url: string): string {
	const cut = url.search(/[?#]/);
	return cut === -1 ? url : url.slice(0, cut);
}
